sp_widget.client_script:
api.controller = function($scope, $location, $window) {
  var c = this;
  c.step = 1;
  c.isSubmitting = false;

  c.data.fullName = '';
  c.data.email = '';
  c.data.dob = '';
  c.data.nationality = '';
  c.data.passportNumber = '';
  c.data.targetCity = '';
  c.data.visaCategory = '';
  c.data.jobTitle = '';
  c.data.salary = null;
  c.data.legalConsent = false;

  c.data.files = {
    passport: null,
    photo: null,
    contract: null,
    degree: null
  };

  c.isValidEmail = function(email) {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
  };

  c.fileSelected = function(element, fileType) {
    var file = element.files[0];
    if (!file) {
      c.data.files[fileType] = null;
      return;
    }

    var reader = new FileReader();
    reader.onload = function(e) {
      $scope.$apply(function() {
        var base64Data = e.target.result.split(',')[1];
        c.data.files[fileType] = {
          name: file.name,
          type: file.type,
          base64: base64Data
        };
      });
    };
    reader.readAsDataURL(file);
  };

  c.goToStep = function(targetStep) {
    if (targetStep === 2) {
      if (!c.data.fullName || !c.data.email || !c.data.dob || !c.data.nationality || !c.data.passportNumber) {
        alert('Please complete all personal details in Step 1.');
        return;
      }
      if (!c.isValidEmail(c.data.email)) {
        alert('Please provide a valid email format.');
        return;
      }
    }

    if (targetStep === 3) {
      if (!c.data.targetCity || !c.data.visaCategory || !c.data.jobTitle || !c.data.salary) {
        alert('Please fill in all relocation and employment details in Step 2.');
        return;
      }
    }

    c.step = targetStep;
  };

  c.submitApplication = function() {
    if (!c.data.legalConsent) {
      alert('Please agree to the § 81a representation authorization.');
      return;
    }

    if (!c.data.fullName || !c.data.email || !c.data.passportNumber) {
      alert('Please complete all required identity fields.');
      return;
    }

    if (!c.data.files.passport || !c.data.files.photo || !c.data.files.contract || !c.data.files.degree) {
      alert('All four document uploads (Passport, Photo, Contract, Degree) are required.');
      return;
    }

    c.isSubmitting = true;
    c.data.action = 'submit_visa_case_with_attachments';

    c.server.update().then(function(response) {
      c.isSubmitting = false;
      if (response && response.result === 'success' && response.caseSysId) {
        var path = $window.location.pathname;
        $window.location.href = path + '?id=gvft_status&sys_id=' + response.caseSysId;
      } else if (response && response.message) {
        alert('Submission error: ' + response.message);
      } else {
        alert('Submission failed. Please check your data and retry.');
      }
    });
  };
};

sp_widget.css:
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');

/* Fixed background for full screen coverage */
.gvft-bg-layer {
  position: fixed;
  top: 0;
  left: 0;
  width: 100vw;
  height: 100vh;
  z-index: 0;
  background: linear-gradient(135deg, #091322 0%, #0e223d 50%, #0a192f 100%);
  pointer-events: none;
}

.gvft-intake-wrapper {
  position: relative;
  z-index: 1;
  font-family: 'Inter', sans-serif !important;
  min-height: 100vh;
  padding: 40px 20px 80px 20px;
}

/* Centered content box */
.gvft-main-container {
  max-width: 820px;
  margin: 0 auto;
  position: relative;
  z-index: 2;
}

/* Header & Titles */
.gvft-header {
  margin-bottom: 30px;
  text-align: left;
}

.main-title {
  color: #ffffff !important;
  font-size: 32px;
  font-weight: 800;
  letter-spacing: -0.5px;
  margin: 0 0 8px 0;
  text-shadow: 0 2px 10px rgba(0, 0, 0, 0.4);
}

.main-subtitle {
  color: #94a3b8;
  font-size: 14px;
  margin: 0;
}

/* Stepper Wizard - Full Width & Centered */
.gvft-wizard-nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 28px;
  width: 100%;
}

.step-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  opacity: 0.5;
  transition: all 0.25s ease;
  min-width: 110px;

  &.active,
  &.completed {
    opacity: 1;
  }
}

.step-circle {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.08);
  color: #94a3b8;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 16px;
  border: 2px solid rgba(255, 255, 255, 0.2);
  transition: all 0.25s ease;
}

.step-item.active .step-circle {
  background: #38bdf8 !important;
  color: #0b1a30 !important;
  border-color: #38bdf8 !important;
  box-shadow: 0 0 16px rgba(56, 189, 248, 0.45);
}

.step-item.completed .step-circle {
  background: #10b981 !important;
  color: #ffffff !important;
  border-color: #10b981 !important;
}

.step-label {
  color: #cbd5e1;
  font-weight: 600;
  font-size: 13px;
  margin-top: 8px;
  text-align: center;
  white-space: nowrap;
}

.step-line {
  flex: 1;
  height: 2px;
  background: rgba(255, 255, 255, 0.15);
  margin: 0 10px 24px 10px;
  transition: background 0.3s ease;

  &.active {
    background: #38bdf8;
  }
}

/* Step Card Container */
.gvft-step-pane {
  background: rgba(15, 23, 42, 0.75);
  border: 1px solid rgba(255, 255, 255, 0.12);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-radius: 14px;
  padding: 32px 36px;
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.45);
  width: 100%;
}

.pane-header {
  margin-bottom: 24px;
}

.step-title {
  color: #ffffff !important;
  font-size: 20px;
  font-weight: 700;
  margin: 0 0 6px 0;

  i {
    color: #38bdf8;
    margin-right: 8px;
  }
}

.instruction-text {
  color: #94a3b8 !important;
  font-size: 14px;
  margin: 0;
}

.form-grid {
  margin-bottom: 12px;
}

.control-label {
  color: #e2e8f0 !important;
  font-size: 13px;
  font-weight: 600;
  margin-bottom: 6px;
  display: block;
}

.text-danger {
  color: #f87171 !important;
}

/* Inputs & Form Controls */
.form-control {
  background: rgba(10, 25, 47, 0.8) !important;
  border: 1px solid rgba(255, 255, 255, 0.18) !important;
  color: #ffffff !important;
  border-radius: 8px !important;
  height: 44px;
  font-size: 14px;
  padding: 8px 14px;
  box-shadow: none !important;

  &:focus {
    background: rgba(10, 25, 47, 0.95) !important;
    border-color: #38bdf8 !important;
    box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.25) !important;
  }

  &::placeholder {
    color: rgba(255, 255, 255, 0.35) !important;
  }
}

select.form-control option {
  background: #0f172a;
  color: #ffffff;
}

.uppercase-input {
  text-transform: uppercase;
}

.gvft-file-input {
  padding: 8px 12px !important;
  line-height: normal;
}

.file-tag {
  display: inline-block;
  margin-top: 6px;
  font-size: 12px;
  color: #38bdf8;
  font-weight: 600;
  background: rgba(56, 189, 248, 0.12);
  padding: 2px 8px;
  border-radius: 4px;
}

/* Legal Representation Box */
.gvft-consent-box {
  background: rgba(10, 25, 47, 0.65);
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 8px;
  padding: 16px 18px;
  margin-top: 20px;
  margin-bottom: 10px;

  .checkbox-container {
    display: flex;
    gap: 12px;
    align-items: flex-start;
    margin: 0;
    cursor: pointer;
  }

  input[type="checkbox"] {
    margin-top: 3px;
    accent-color: #38bdf8;
    width: 18px;
    height: 18px;
    cursor: pointer;
  }

  .consent-text {
    font-size: 13px;
    color: #cbd5e1;
    line-height: 1.5;

    strong {
      color: #38bdf8;
    }
  }
}

/* Button Rows */
.gvft-button-row {
  margin-top: 28px;

  &.text-right {
    text-align: right;
  }

  &.between-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
  }
}

.btn-prev {
  background: rgba(255, 255, 255, 0.08) !important;
  color: #ffffff !important;
  border: 1px solid rgba(255, 255, 255, 0.22) !important;
  height: 44px;
  padding: 0 24px;
  border-radius: 8px;
  font-weight: 600;
  transition: all 0.2s;

  &:hover {
    background: rgba(255, 255, 255, 0.18) !important;
  }
}

.btn-next {
  background: #38bdf8 !important;
  color: #0b1a30 !important;
  border: none !important;
  height: 44px;
  padding: 0 28px;
  border-radius: 8px;
  font-weight: 700;
  transition: all 0.2s ease;

  &:hover {
    background: #0ea5e9 !important;
    box-shadow: 0 4px 14px rgba(56, 189, 248, 0.35);
  }
}

.btn-submit {
  background: #10b981 !important;
  color: #ffffff !important;
  border: none !important;
  height: 44px;
  padding: 0 28px;
  border-radius: 8px;
  font-weight: 700;
  box-shadow: 0 4px 14px rgba(16, 185, 129, 0.35);

  &:hover {
    background: #059669 !important;
  }

  &[disabled] {
    opacity: 0.6;
    cursor: not-allowed;
  }
}

sp_widget.script:
(function() {
  if (input && input.action === 'submit_visa_case_with_attachments') {
    data.result = 'pending';

    var caseTable = 'x_2023506_german_1_imm_case';
    var docTable  = 'x_2023506_german_1_case_doc';

    try {
      var gr = new GlideRecord(caseTable);
      gr.initialize();

      // 1. Set Parent Case fields
      gr.setValue('u_candidate_name', input.fullName);
      gr.setValue('u_candidate_email', String(input.email).trim().toLowerCase());
      gr.setValue('u_candidate_dob', input.dob);
      gr.setValue('u_nationality', input.nationality);
      gr.setValue('u_passport_number', String(input.passportNumber).toUpperCase().trim());
      gr.setValue('u_target_city', input.targetCity);
      gr.setValue('u_visa_category', input.visaCategory);
      gr.setValue('u_job_title', input.jobTitle);
      gr.setValue('u_salary_euro', input.salary);
      gr.setValue('u_fast_track_authorized', input.legalConsent);
      gr.setValue('state', '1'); // 1 = Open
      gr.setValue('u_fee_status', 'Pending');

      var caseSysId = gr.insert();

      if (!caseSysId) {
        data.result = 'error';
        data.message = 'Could not insert case record in ' + caseTable;
        return;
      }

      gr.get(caseSysId);
      data.result = 'success';
      data.caseSysId = caseSysId;

      var attachmentWriter = new GlideSysAttachment();

      // 2. Child doc helper using exact Choice Values ('1', '2', '3', '4')
      function createCaseDocument(choiceValue, labelText, fileObj) {
        if (!fileObj || !fileObj.base64) return;

        var grDoc = new GlideRecord(docTable);
        grDoc.initialize();
        grDoc.setValue('u_case', caseSysId);
        grDoc.setValue('u_document_name', choiceValue);
        grDoc.setValue('u_file_name', fileObj.name);
        grDoc.setValue('u_status', 'Submitted');
        grDoc.setValue('u_review_notes', 'Pending initial caseworker verification');
        var docSysId = grDoc.insert();

        var mimeType = fileObj.type || 'application/pdf';

        // Attach directly to the child document record
        if (docSysId && grDoc.get(docSysId)) {
          var childAttachId = attachmentWriter.writeBase64(grDoc, fileObj.name, mimeType, fileObj.base64);
          if (childAttachId && grDoc.isValidField('u_attachment')) {
            grDoc.setValue('u_attachment', childAttachId);
            grDoc.update();
          }
        }

        // Attach also to parent case record
        attachmentWriter.writeBase64(gr, labelText + ' - ' + fileObj.name, mimeType, fileObj.base64);
      }

      // 3. Process all 4 uploaded files
      if (input.files) {
        createCaseDocument('1', 'Passport',           input.files.passport);
        createCaseDocument('2', 'Passport Photo',     input.files.photo);
        createCaseDocument('3', 'Job Contract',       input.files.contract);
        createCaseDocument('4', 'Degree Certificate', input.files.degree);
      }

      data.caseNumber = gr.getValue('number');

    } catch (ex) {
      data.result = 'error';
      data.message = 'Server execution failure: ' + ex.message;
    }
  }
})();
